function Navbar() {
  const [open, setOpen] = useState(false);
  const reduceMotion = useReducedMotion();
  const openerRef = useRef<HTMLElement | null>(null);
  const drawerRef = useRef<HTMLElement | null>(null);
  const location = useLocation();
  useEffect(() => { setOpen(false); window.scrollTo({ top:0, behavior:'smooth' }); }, [location.pathname]);
  useEffect(() => {
    if (!open) { openerRef.current?.focus(); return; }
    const focusable = () => Array.from(drawerRef.current?.querySelectorAll<HTMLElement>('a[href],button:not([disabled])') ?? []);
    focusable()[0]?.focus();
    const close = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { setOpen(false); return; }
      if (event.key === 'Tab') {
        const items = focusable();
        if (!items.length) return;
        if (event.shiftKey && document.activeElement === items[0]) { event.preventDefault(); items[items.length-1]?.focus(); }
        else if (!event.shiftKey && document.activeElement === items[items.length-1]) { event.preventDefault(); items[0]?.focus(); }
      }
    };
    window.addEventListener('keydown', close);
    return () => window.removeEventListener('keydown', close);
  }, [open]);
  return <header className="sticky top-0 z-40 border-b border-white/[.08] bg-[#08071b]/90 backdrop-blur-xl">
    <div className="mx-auto flex h-[76px] max-w-[1380px] items-center justify-between px-5 lg:px-10">
      <Logo />
      <nav aria-label="Main navigation" className="hidden items-center gap-5 xl:flex">
        {navLinks.map(([label,path]) => <Link key={path} to={path} className={`text-[12px] transition-colors hover:text-amber-200 ${location.pathname === path ? 'text-amber-200' : 'text-[#d8d4f0]'}`} data-testid={`nav-${label.toLowerCase()}`}>{label}</Link>)}
      </nav>
      <div className="hidden items-center gap-3 xl:flex">
        <Link to="/free-tools" aria-label="Open free tools" className="rounded-full p-2 text-lavender hover:bg-white/5 hover:text-cyan-200" data-testid="nav-free-tools"><Calculator size={17}/></Link>
        <Link to="/consultations" className="button-gold !px-4 !py-2.5 !text-xs" data-testid="nav-book-consultation">Book consultation <ArrowRight size={14}/></Link>
      </div>
      <button aria-label="Open navigation menu" aria-expanded={open} onClick={e => {openerRef.current=e.currentTarget;setOpen(true)}} className="rounded-xl border border-white/15 p-2.5 text-[#fff8eb] xl:hidden" data-testid="button-open-menu"><Menu size={20}/></button>
    </div>
    <AnimatePresence>
      {open && <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }} className="fixed inset-0 z-50 bg-[#050411]/80 backdrop-blur-sm xl:hidden" onClick={() => setOpen(false)}>
        <motion.aside ref={drawerRef} initial={reduceMotion?false:{ x:'100%' }} animate={{ x:0 }} exit={{ x:reduceMotion?0:'100%' }} transition={reduceMotion?{duration:0}:{ type:'spring', damping:28, stiffness:240 }} role="dialog" aria-modal="true" aria-label="Site navigation" onClick={e => e.stopPropagation()} className="ml-auto flex h-full w-[min(88vw,390px)] flex-col border-l border-white/10 bg-[#0c0a22] p-6">
          <div className="mb-9 flex items-center justify-between"><Logo/><button aria-label="Close navigation menu" onClick={() => setOpen(false)} className="rounded-lg p-2 text-[#d8d4f0]" data-testid="button-close-menu"><X size={20}/></button></div>
          <nav className="flex flex-col gap-1">{[['Home','/'],...navLinks,['Reports','/reports'],['Free tools','/free-tools'],['FAQ','/faq']].map(([label,path]) => <Link key={path} to={path} onClick={() => setOpen(false)} className="flex items-center justify-between border-b border-white/[.07] py-3.5 text-[15px] text-[#e5e1f5] hover:text-amber-200" data-testid={`mobile-nav-${label.toLowerCase().replaceAll(' ','-')}`}>{label}<ChevronRight size={15} className="text-[#8a84ab]"/></Link>)}</nav>
          <Link to="/consultations" className="button-gold mt-7 justify-center" data-testid="mobile-book-consultation">Explore consultations <ArrowRight size={16}/></Link>
          <p className="mt-auto text-xs leading-relaxed text-[#8884a7]">Traditional wisdom for reflection and perspective. Outcomes are not guaranteed.</p>
        </motion.aside>
      </motion.div>}
    </AnimatePresence>
  </header>;
}

