function ConsultGrid({featured=false}:{featured?:boolean}) {
  const [filter,setFilter]=useState('All');const [expanded,setExpanded]=useState('');
  const filters=['All','Astrology','Numerology','Combined','Vastu'];
  const selected=useMemo(()=>consultations.filter(i=>filter==='All'||i.category===filter),[filter]);
  const shown=featured?selected.slice(0,4):selected;
  return <div>
    <div className="mb-7 flex flex-wrap gap-2" role="group" aria-label="Filter consultations">{filters.map(f=><button key={f} onClick={()=>setFilter(f)} aria-pressed={filter===f} className={`filter-chip ${filter===f?'filter-chip-active':''}`} data-testid={`filter-consultation-${f.toLowerCase()}`}>{f}</button>)}</div>
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{shown.map(i=><ConsultationCard key={i.slug} item={i} expanded={expanded===i.slug} onToggle={()=>setExpanded(expanded===i.slug?'':i.slug)}/>)}</div>
    {featured&&<div className="mt-8 text-center"><ButtonLink to="/consultations" secondary testId="link-all-consultations">View all consultation packages <ArrowRight size={16}/></ButtonLink></div>}
  </div>;
}

