function CourseCards({filterable=true,featured=false}:{filterable?:boolean;featured?:boolean}) {
  const [filter,setFilter]=useState('All');const options=['All','Numerology','Vedic Astrology','Advanced Consultation Training'];
  const categoryFor=(course:Item)=>course.slug.includes('numerology')?'Numerology':course.slug==='astrology-consultation-mastery'?'Advanced Consultation Training':'Vedic Astrology';
  const list=filterable?courses.filter(c=>filter==='All'||categoryFor(c)===filter):courses;
  return <><div className="mb-7 flex flex-wrap gap-2">{filterable&&options.map(f=><button key={f} onClick={()=>setFilter(f)} aria-pressed={filter===f} className={`filter-chip ${filter===f?'filter-chip-active':''}`} data-testid={`filter-course-${f.toLowerCase().replaceAll(' ','-')}`}>{f}</button>)}</div>
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{(featured?list.slice(0,3):list).map(c=><article className="glass flex flex-col rounded-[22px] p-6 transition duration-300 hover:-translate-y-1 hover:border-violet-200/30" key={c.slug} data-testid={`card-course-${c.slug}`}>
      <div className="flex items-center justify-between"><span className="rounded-full border border-cyan-100/20 px-3 py-1 text-[10px] uppercase tracking-[.16em] text-cyan-100">{c.level}</span><GraduationCap size={18} className="text-amber-200"/></div>
      <h3 className="serif mt-5 text-2xl leading-tight text-[#fff8eb]">{c.title}</h3><p className="mt-3 min-h-12 text-sm leading-6 text-[#aaa6c9]">{c.description}</p>
      <div className="mt-5 grid grid-cols-2 gap-3 border-y border-white/10 py-4"><div><span className="eyebrow !text-[9px]">Course fee</span><p className="mt-1 font-medium text-amber-100">{c.price}</p></div><div><span className="eyebrow !text-[9px]">Duration</span><p className="mt-1 text-sm text-[#d8d4f0]">{c.duration??'Not specified'}</p></div></div>
      <p className="mt-4 text-xs leading-5 text-[#aaa6c9]"><span className="text-[#d8d4f0]">For:</span> {c.audience}</p>
      <div className="mt-5 flex gap-2"><Link to={`/courses/${c.slug}`} className="button-outline flex-1 justify-center !px-3 !py-3" data-testid={`button-curriculum-${c.slug}`}>View curriculum</Link><Link to={`/payment/${c.slug}`} className="button-gold flex-1 justify-center !px-3 !py-3" data-testid={`button-enrol-${c.slug}`}>Enquire / enrol</Link></div>
    </article>)}</div>
    {featured&&<div className="mt-8 text-center"><ButtonLink to="/courses" secondary testId="link-all-courses">Explore all courses <ArrowRight size={15}/></ButtonLink></div>}
  </>;
}

function CalculatorWidget() {
  const [name,setName]=useState('');const [date,setDate]=useState('');const [result,setResult]=useState<{birth:number;life:number}|null>(null);const [error,setError]=useState('');
  const run=(e:FormEvent)=>{e.preventDefault();const computed=calculateBirthNumbers(date);if(!computed){setError('Please enter a valid date of birth that is not in the future.');setResult(null);return;}setResult(computed);setError('');};
  return <div className="glass overflow-hidden rounded-[26px]"><div className="grid lg:grid-cols-[.9fr_1.1fr]">
    <div className="p-6 md:p-9"><div className="service-icon"><Calculator size={20}/></div><h3 className="serif mt-5 text-3xl">A small beginning</h3><p className="mt-3 text-sm leading-6 text-[#aaa6c9]">Explore two introductory numerology calculations, privately in your browser. Your details are not sent or saved.</p>
      <form onSubmit={run} className="mt-7 space-y-4" noValidate>
        <label className="form-label">Name <span className="text-[#817d9e]">(optional)</span><input value={name} onChange={e=>setName(e.target.value)} className="form-input mt-2" placeholder="Name" autoComplete="off" data-testid="input-calculator-name"/></label>
        <label className="form-label">Date of birth<input required type="date" value={date} onChange={e=>setDate(e.target.value)} className="form-input mt-2" data-testid="input-calculator-date"/></label>
        {error&&<p role="alert" className="text-sm text-rose-200" data-testid="status-calculator-error">{error}</p>}
        <button className="button-gold w-full justify-center" type="submit" data-testid="button-calculate-numerology">Calculate numbers <ArrowRight size={15}/></button>
      </form>
    </div>
    <div className="relative flex min-h-[320px] flex-col justify-center border-t border-white/10 bg-[#0a0920]/70 p-6 md:p-9 lg:border-l lg:border-t-0">
      {result?<div className="fade-up" data-testid="result-numerology"><p className="eyebrow">{name.trim()?`A reflection for ${name.trim()}`:'Your introductory reading'}</p><div className="mt-5 grid grid-cols-2 gap-4">{[['Birth Number',result.birth],['Life Path Number',result.life]].map(([label,num])=><div key={label} className="rounded-2xl border border-violet-100/15 bg-white/[.035] p-5"><p className="text-xs text-[#aaa6c9]">{label}</p><p className="serif mt-2 text-5xl text-amber-100">{num}</p></div>)}</div><p className="mt-5 text-sm leading-6 text-[#c6c1dc]">{numberReflection(result.birth)} {result.life!==result.birth&&numberReflection(result.life)}</p><p className="mt-4 text-[11px] text-[#928dad]">Introductory traditional numerology tool; not a prediction or professional advice.</p><Link to="/consultations" className="mt-5 inline-flex items-center gap-2 text-sm text-cyan-200" data-testid="link-calculator-consultation">Explore a personal consultation <ArrowRight size={14}/></Link></div>
      :<div><div className="relative mx-auto mb-6 grid h-28 w-28 place-items-center rounded-full border border-amber-100/20 text-amber-100"><div className="absolute inset-3 rounded-full border border-cyan-100/20"/><Orbit size={38}/><span className="absolute -right-2 top-4 text-cyan-200"><Sparkles size={15}/></span></div><h4 className="serif text-center text-2xl">The method, made visible</h4><p className="mx-auto mt-3 max-w-md text-center text-sm leading-6 text-[#aaa6c9]">Birth Number reduces the day of birth, preserving 11 and 22. Life Path adds every digit in the full birth date, then reduces the sum, also preserving 11 and 22.</p></div>}
    </div>
  </div></div>;
}

