function TestimonialsPreview() {
  const [filter,setFilter]=useState('All');const filters=['All',...testimonials.map(t=>t.category)];
  const list=testimonials.filter(t=>filter==='All'||t.category===filter);
  return <section className="border-y border-white/[.07] bg-[#100e27]/55 py-24 md:py-28"><Container><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><SectionTitle label="Voices · preview placeholders" title="Stories, when they are ready." body="These supplied sample statements are placeholders only—not verified client reviews."/></div><ButtonLink to="/testimonials" secondary testId="link-testimonials-page">View testimonials <ArrowRight size={15}/></ButtonLink></div><div className="mb-6 flex flex-wrap gap-2">{filters.map(f=><button key={f} onClick={()=>setFilter(f)} aria-pressed={filter===f} className={`filter-chip ${filter===f?'filter-chip-active':''}`} data-testid={`filter-testimonial-${f.toLowerCase().replaceAll(' ','-')}`}>{f}</button>)}</div><div className="grid gap-4 md:grid-cols-3">{list.map((t,i)=><figure key={t.category} className="glass rounded-[22px] p-6" data-testid={`card-testimonial-${i}`}><div className="flex items-center gap-2 text-amber-200"><Quote size={16}/><span className="text-[10px] uppercase tracking-[.15em]">{t.category}</span></div><blockquote className="serif mt-6 text-xl leading-relaxed text-[#f3efff]">“{t.text}”</blockquote><figcaption className="mt-6 border-t border-white/10 pt-4 text-[10px] tracking-wide text-[#918bac]">SAMPLE PLACEHOLDER · NOT A VERIFIED REVIEW</figcaption></figure>)}</div></Container></section>;
}

function ArticleCards({limit}:{limit?:number}) {return <div className="mt-8 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{articles.slice(0,limit).map(a=><Link to={`/knowledge?article=${a.slug}`} className="article-tile" key={a.slug} data-testid={`article-${a.slug}`}><span className="text-[10px] uppercase tracking-[.17em] text-[#8c6e47]">{a.category} · SAMPLE EDUCATIONAL CONTENT</span><h3 className="serif mt-4 text-2xl leading-tight text-[#291e3e]">{a.title}</h3><p className="mt-3 text-sm leading-6 text-[#6d6374]">{a.excerpt}</p><span className="mt-5 inline-flex items-center gap-2 text-xs text-[#705596]">Read article <ArrowRight size={14}/></span></Link>)}</div>}

function FinalCta() {return <section className="relative overflow-hidden py-24 text-center md:py-32"><CosmicBackdrop/><Container className="relative z-10"><div className="mx-auto mb-7 grid h-16 w-16 place-items-center rounded-full border border-amber-100/25 bg-white/[.025] text-amber-100"><Orbit size={27}/></div><Eyebrow>Begin with a question</Eyebrow><h2 className="serif mx-auto mt-5 max-w-3xl text-4xl leading-tight text-[#fff8eb] md:text-6xl">Your journey of self-discovery begins here.</h2><p className="mx-auto mt-5 max-w-xl leading-7 text-[#aaa6c9]">Explore traditional wisdom, understand your possibilities, and approach life’s questions with greater clarity.</p><div className="mt-8 flex flex-wrap justify-center gap-3"><ButtonLink to="/consultations" testId="cta-consultations">Explore consultations <ArrowRight size={15}/></ButtonLink><ButtonLink to="/courses" secondary testId="cta-courses">Discover courses <ArrowRight size={15}/></ButtonLink><ButtonLink to="/contact" secondary testId="cta-contact">Contact Astro Nova <ArrowRight size={15}/></ButtonLink></div></Container></section>}

function About() {
  const milestones=[['M.Tech.','IIT Roorkee'],['UPSC Geoscientist','All-India Rank 95'],['Junior Scientist (Geologist)','Selected in the Atomic Energy sector at Jaduguda'],['Schlumberger','Selected'],['Two research papers','One in an international publication; another associated with national-level scientific research']];
  return <PageShell><PageIntro label="Founder · Astro Nova" title="A life between inquiry and tradition." description="The journey of Pradeep Kumarr Naik—shaped by spiritual learning, scientific education and the work of making complex ideas clear."/>
    <Container className="pb-20"><div className="grid gap-12 lg:grid-cols-[.72fr_1.28fr]"><FounderPortrait className="mx-auto aspect-[4/5] w-full max-w-[370px] self-start"/><div className="space-y-12">
      <div><Eyebrow>Pradeep Kumarr Naik</Eyebrow><p className="serif mt-4 text-2xl leading-relaxed text-[#e6dcfa]">Founder of NOVA ASTRO ZONE™ / Astro Nova</p><p className="mt-2 text-sm text-[#aaa6c9]">Astrologer · Numerologist · Vastu Consultant · Palmistry Practitioner</p><p className="mt-5 leading-7 text-[#c6c1dc]">“My journey has been shaped by a lifelong interest in spirituality, self-inquiry, scientific learning and the traditional wisdom of India. Through Astro Nova, my objective is to help individuals explore life's questions with greater clarity by combining traditional knowledge with analytical thinking and a balanced perspective.”</p></div>
      <div><SectionTitle label="Early spiritual inquiry" title="My first Guru — my mother."/><p className="leading-7 text-[#b7b2cf]">The founder describes his early spiritual journey as beginning with his mother's influence and his association with a Rishikul environment at around age ten. At around thirteen, he was introduced to Brahma Tattva under the guidance of his Guru, Swami Hari Santoshanand Ji.</p><p className="mt-4 leading-7 text-[#b7b2cf]">The practices described in his account are Naam Brahma Kriya, Jyoti Darshan Kriya, Amritpaan Kriya and Anahad Naad Kriya. His interests have also included Yoga Nidra, meditation, self-inquiry, contemplative disciplines and the study of Kundalini-related practices. These are presented as his personal spiritual journey.</p><div className="mt-5 flex flex-wrap gap-2">{['Naam Brahma Kriya','Jyoti Darshan Kriya','Amritpaan Kriya','Anahad Naad Kriya'].map(x=><span className="rounded-full border border-violet-100/15 px-3 py-2 text-xs text-[#c9c2dd]" key={x}>{x}</span>)}</div></div>
      <div><SectionTitle label="From Brahmavidya to Jyotish" title="A Kundali is a mirror of possibilities."/><p className="leading-7 text-[#b7b2cf]">His interests expanded into Vedic Astrology, Numerology, Vastu Shastra and Palmistry. The supplied biography describes approximately seven years of professional engagement in these traditional disciplines and experience analysing more than 5,000 horoscopes.</p><blockquote className="serif mt-6 border-l border-amber-200/50 pl-5 text-2xl italic leading-relaxed text-amber-100">“A Kundali is not merely a prediction of the future; it is a mirror of possibilities.”</blockquote></div>
      <div><SectionTitle label="Academic foundation" title="A rigorous education, held in its proper context." body="These credentials inform the founder’s education and work history; they are not presented as scientific validation of astrology."/><div className="space-y-0">{milestones.map(([title,copy],i)=><div className="relative grid grid-cols-[36px_1fr] gap-4 border-l border-violet-100/20 pb-7 pl-5 last:pb-0" key={title}><span className="absolute -left-[5px] top-1 h-2.5 w-2.5 rounded-full bg-amber-200 shadow-[0_0_14px_rgba(245,199,107,.45)]"/><span className="text-[10px] text-[#857fa3]">0{i+1}</span><div><h3 className="text-sm font-medium text-[#eee9fb]">{title}</h3><p className="mt-1 text-sm leading-6 text-[#aaa6c9]">{copy}</p></div></div>)}</div></div>
      <div><SectionTitle label="Teaching & mentoring" title="Seventeen years of making ideas understandable."/><p className="leading-7 text-[#b7b2cf]">More than 17 years of teaching and mentoring experience, including guiding thousands of students preparing for IIT-JEE and NEET. The biography notes an association with Bansal Classes, Resonance and Eduwave, Kota, Rajasthan. This experience informs a clear, structured and analytical approach to explanation.</p></div>
      <div><SectionTitle label="The approach" title="Three complementary dimensions."/><div className="grid gap-3 sm:grid-cols-3">{[['01','Spiritual wisdom','Brahmavidya, Vedantic inquiry, meditation and spiritual discipline.'],['02','Traditional knowledge','Jyotish, Numerology, Vastu Shastra and Palmistry.'],['03','Analytical thinking','Scientific education, research, observation and teaching experience.']].map(([n,t,d])=><div className="glass rounded-2xl p-5" key={n}><span className="serif text-2xl text-amber-100">{n}</span><h3 className="serif mt-3 text-lg">{t}</h3><p className="mt-2 text-xs leading-5 text-[#aaa6c9]">{d}</p></div>)}</div></div>
      <p className="serif text-2xl leading-relaxed text-[#eee7ff]">“My philosophy is simple: understand your possibilities, recognise your strengths, approach challenges thoughtfully, and make informed decisions.”</p>
      <div><Eyebrow>Owner-supplied imagery</Eyebrow><p className="mt-3 text-sm leading-6 text-[#aaa6c9]">Optional gallery reserved for approved owner assets. No placeholder client or event imagery is used.</p></div>
      <ButtonLink to="/consultations" testId="about-consultations">Explore consultations <ArrowRight size={15}/></ButtonLink>
    </div></div></Container></PageShell>;
}

const astrologyTopics=['Birth Chart Analysis','Career and Profession','Education and Competitive Examinations','Business and Entrepreneurship','Finance and Financial Patterns','Marriage and Relationships','Family and Personal Life','Annual Forecast','Prashna / Question Consultation','Timing and Life Cycles','Personal Guidance','Health-related traditional astrological interpretations'];
const numerologyTopics=['Birth Number','Life Path / Conductor Number','Name Analysis','Name Correction','Compound Numbers','Lo Shu Grid','Personal Year and Personal Month','Personal Cycles','Career and Finance','Relationship Compatibility','Business and Brand Numerology','Mobile Number Analysis','Lucky Date Selection'];
